
SELECT p.id,s.id,DATE_ADD(CURDATE(),INTERVAL 30 DAY),'I am a second-year student looking for a quiet room near campus.',p.monthly_rent,p.deposit_amount,'pending',DATE_ADD(NOW(),INTERVAL 12 HOUR),NOW()
FROM properties p JOIN users s ON s.email='student@emergex.test' WHERE p.title='Braamfontein Studio Living';

SELECT b.id,b.deposit_amount,'not_paid',NOW() FROM bookings b LEFT JOIN escrow_transactions e ON e.booking_id=b.id WHERE e.id IS NULL;
